using System;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BlazarDiskOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/BlazarDisk Omen Data")]
public class BlazarDiskOmenData : OmenData
{
	[Header("Blazar Disk")]
	[SerializeField]
	private Effect blazarDiskEffect;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private bool resetBetweenBattles;

	private Func<int, int> omenAction;

	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		Action omenAboutToTriggerAction = delegate
		{
			UnitEffects component = playerGameObjectReference.value.GetComponent<UnitEffects>();
			component.AddEffect(blazarDiskEffect, EffectsValues.NO_VALUE);
			component.IsEffectActiveGetEffectInstance(blazarDiskEffect).PlayBlinkingFeedback();
			omenInstance.PlayBlinkingFeedback();
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.BlazarDiskStartOfBattleOmenAction = delegate
		{
			if (OmenAboutToTrigger())
			{
				omenAboutToTriggerAction();
			}
		};
		omenAction = delegate(int purifyAmount)
		{
			ActivateOmen();
			omenInstance.UpdateOmenCounter();
			if (OmenTriggered())
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omenInstance.StopBlinkingFeedback();
				playerGameObjectReference.value.GetComponent<UnitEffects>().RemoveEffect(blazarDiskEffect, activateFeedback: false);
				return purifyAmount * 2;
			}
			if (OmenAboutToTrigger())
			{
				omenAboutToTriggerAction();
				return purifyAmount;
			}
			return purifyAmount;
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyBlazarDiskOmenAction = omenAction;
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
			this.omenInstance = omenInstance;
		}
	}

	private bool OmenTriggered()
	{
		return counter == 0;
	}

	private bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 1;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.BlazarDiskStartOfBattleOmenAction = null;
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyBlazarDiskOmenAction = null;
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
			omenInstance = null;
		}
	}
}
